from typing import List

def shell_degeneracy(n: int) -> int:
    return 2 * n * n

def noble_gas(n: int) -> int:
    return sum(shell_degeneracy(k + 1) for k in range(n))

def ho_degeneracy(N: int) -> int:
    return (N + 1) * (N + 2)

def magic_ho(n: int) -> int:
    return sum(ho_degeneracy(N) for N in range(n + 1))

def main() -> None:
    for n in range(1, 20):
        assert 3 * noble_gas(n) == n * (n + 1) * (2 * n + 1)
    for n in range(20):
        assert 3 * magic_ho(n) == (n + 1) * (n + 2) * (n + 3)
    print('Coulomb  F(1..5) =', [noble_gas(n) for n in range(1, 6)])
    print('Oscillator G(0..5) =', [magic_ho(n) for n in range(6)])

if __name__ == '__main__':
    main()

from typing import List

def angular_count(n: int) -> int:
    return sum(2 * l + 1 for l in range(n))

def shell_degeneracy(n: int) -> int:
    return 2 * n * n

def main() -> None:
    for n in range(12):
        assert angular_count(n) == n * n
        assert shell_degeneracy(n) == 2 * angular_count(n)
    rows: List[int] = [shell_degeneracy(n) for n in range(1, 5)]
    print('idealized row lengths 2n^2 =', rows)

if __name__ == '__main__':
    main()

from typing import List

def build_diagonal_hamiltonian(energies: List[float]) -> List[List[float]]:
    d = len(energies)
    return [[energies[i] if i == j else 0.0 for j in range(d)] for i in range(d)]

def matvec(m: List[List[float]], v: List[float]) -> List[float]:
    return [sum(row[k] * v[k] for k in range(len(v))) for row in m]

def main() -> None:
    energies = [-13.6, -3.4, -1.51, -0.85]
    H = build_diagonal_hamiltonian(energies)
    assert all(H[i][j] == H[j][i] for i in range(4) for j in range(4))
    for j, E in enumerate(energies):
        e = [1.0 if i == j else 0.0 for i in range(4)]
        assert matvec(H, e) == [E * c for c in e]
    print('trace =', sum(H[i][i] for i in range(4)), '= sum of shell energies')

if __name__ == '__main__':
    main()

