function CUMULATIVE_FILLINGS(a, b, c, M):
    F <- array of size M+1
    running <- 0
    for k from 0 to M:
        running <- running + (a*k*k + b*k + c)
        F[k] <- running
    return F

function RECOVER_LAW(F0, F1, F2, F3):
    d1 <- F1 - F0;  d2 <- F2 - F1;  d3 <- F3 - F2
    a <- (d3 - 2*d2 + d1) / 2
    b <- (d2 - d1) - 3*a
    c <- d1 - a - b
    return (a, b, c)

